S = "Hakeem Force Academy"
QS = [
 (S, "How many letters does the Pashto alphabet have according to the most commonly cited reference count?", ["38", "45", "32", "52"], 1,
  "The Pashto alphabet is written in an extended Arabic script and is most commonly cited as having 45 letters.", "Some learner guides count 44 letters, so sources differ slightly; 45 is the figure candidates and many references use.", [107, 1736, 1737, 3226]),
 (S, "Which book is generally regarded as the first book written in the Pashto language?", ["Khair-ul-Bayan", "Pata Khazana", "Makhzan-e-Afghani", "Tarikh-e-Sher Shahi"], 0,
  "Khair-ul-Bayan, written by Bayazid Ansari (Pir Roshan) in the 16th century, is generally regarded as the first Pashto book.", "Pata Khazana is a disputed anthology of early Pashto poets, so some sources name other early works.", [3320]),
 (S, "A bus has 30 passengers and two thirds of them are boys, the rest are girls. How many girls are there?", ["20", "15", "10", "5"], 2,
  "Boys = 2/3 of 30 = 20. Girls = 30 - 20 = 10.", "The girls are 1/3 of the passengers, which is 33.33 percent.", [1930]),
 (S, "There are 30 passengers in a bus and one third of them are men, the rest are women. What is the percentage of women?", ["33.33 percent", "50 percent", "75 percent", "66.67 percent"], 3,
  "Women = 2/3 of the passengers. 2/3 x 100 = 66.67 percent.", "Men are 10 of the 30 passengers and women are 20.", [859]),
 (S, "Which Quetta-area peak, also called Loe Sar Nekan, is generally given as the highest peak of Balochistan?", ["Zarghun Ghar", "Takatu", "Chiltan", "Kuchnai Saar"], 0,
  "Zarghun Ghar, near Quetta, at about 3,578 metres is generally given as the highest peak in Balochistan.", "Sources differ a little on its exact height and name; Kuchnai Saar (about 3,404 m) is listed next.", [287, 2935]),
 (S, "Change the narration into indirect speech: She said to me, \"Can you give me your pen?\"", ["She asked me if I could give her my pen.", "She told me that can I give her my pen.", "She said me whether I can give her pen.", "She asked me that I can give me my pen."], 0,
  "A question in direct speech becomes a reporting verb asked plus if, and the tense and pronouns change: can becomes could, you becomes I, me becomes her.", "In indirect speech a yes or no question is joined with if or whether and has no question mark.", [1499]),
 (S, "Who discovered penicillin?", ["Louis Pasteur", "Joseph Lister", "Edward Jenner", "Alexander Fleming"], 3,
  "Alexander Fleming, a Scottish scientist, discovered penicillin in 1928 from the mould Penicillium.", "Fleming shared the 1945 Nobel Prize in Medicine with Florey and Chain.", [33, 4158]),
 (S, "A car travels at 60 km per hour. How much distance will it cover in 20 minutes?", ["10 km", "30 km", "15 km", "20 km"], 3,
  "20 minutes is 20/60 = 1/3 of an hour. Distance = 60 x 1/3 = 20 km.", "Distance equals speed times time.", [1857]),
 (S, "What is 30 percent of 30?", ["9", "3", "10", "30"], 0,
  "30 percent of 30 = 30/100 x 30 = 9.", "10 percent of a number is found by dividing it by 10.", [896]),
 (S, "Approximately what percentage of Pakistan's population is non-Muslim according to the 2023 census?", ["12 percent", "0.5 percent", "3.65 percent", "8 percent"], 2,
  "The 2023 census gave Muslims 96.35 percent, which leaves about 3.65 percent non-Muslim.", "Hindus (about 1.61 percent) and Christians (about 1.37 percent) are the largest minorities, and Ahmadis are listed separately.", [3268]),
 (S, "What is 5/7 as a percentage (to two decimal places)?", ["75.00 percent", "70.00 percent", "71.43 percent", "57.14 percent"], 2,
  "5 divided by 7 = 0.714285. Multiplying by 100 gives 71.43 percent.", "1/7 is about 14.29 percent.", [2627]),
 (S, "During which years was the First World War fought?", ["1914 to 1918", "1912 to 1916", "1916 to 1920", "1939 to 1945"], 0,
  "The First World War began in 1914 and ended in 1918 with the armistice of 11 November.", "The Second World War was fought from 1939 to 1945.", [1070]),
 (S, "One side of a right-angled triangle is 8 and the perpendicular is 6. What is the length of the third side (hypotenuse)?", ["14", "12", "7", "10"], 3,
  "By Pythagoras, hypotenuse squared = 8 squared + 6 squared = 64 + 36 = 100, so the hypotenuse is 10.", "3, 4, 5 and its multiples such as 6, 8, 10 are Pythagorean triples.", [1890]),
 (S, "In a right-angled triangle, sine of an angle is the perpendicular divided by what?", ["Base", "Hypotenuse", "Perpendicular", "Sum of the sides"], 1,
  "Sin of an angle = perpendicular / hypotenuse.", "Cos is base / hypotenuse and tan is perpendicular / base.", [2438]),
 (S, "Which ancient civilization flourished in the Peshawar valley?", ["Mohenjo-daro", "Mehrgarh", "Gandhara", "Harappa"], 2,
  "The Peshawar valley was the heart of the Gandhara civilization, with Purushapura (Peshawar) as a major city.", "Gandhara is famous for Greco-Buddhist art.", [3665]),
 (S, "What is the correct thing to do with the engine of your vehicle at a petrol pump?", ["Keep it running", "Switch it off", "Rev it up", "Park on the road"], 1,
  "Petrol vapour can catch fire from sparks, so the engine must be switched off while refuelling.", "Smoking and using mobile phones at a petrol pump are also unsafe.", [2529]),
 (S, "What is photosynthesis?", ["Breakdown of food in animals", "Loss of water from leaves", "Absorption of water by roots", "Making food by green plants using sunlight, water and carbon dioxide"], 3,
  "In photosynthesis, plants use chlorophyll in chloroplasts and sunlight to turn carbon dioxide and water into glucose and oxygen.", "Photosynthesis releases the oxygen we breathe.", [920, 3243]),
 (S, "In which year was the Pirpur Report on the grievances of Muslims in Congress provinces published?", ["1938", "1930", "1947", "1940"], 0,
  "The Pirpur Report, prepared by a committee of the Muslim League headed by Raja Syed Muhammad Mehdi of Pirpur, came out in 1938.", "It listed complaints against Congress rule in the provinces from 1937.", [1285]),
 (S, "Fill in the blank with the correct preposition: He will not approve ___ your plan.", ["with", "of", "to", "for"], 1,
  "The verb approve takes the preposition of when it means to think well of something.", "Disapprove is also followed by of.", [1558, 248]),
 (S, "Which is the largest planet of the solar system?", ["Saturn", "Neptune", "Jupiter", "Earth"], 2,
  "Jupiter is the largest planet, with a diameter of about 143,000 km.", "Saturn is the second largest planet.", [3805]),
 (S, "Who won the Battle of Plassey (1757)?", ["Nawab Siraj-ud-Daula", "The French", "The Marathas", "The British East India Company"], 3,
  "The East India Company under Robert Clive defeated Nawab Siraj-ud-Daula of Bengal, helped by the betrayal of Mir Jafar.", "The victory began British rule in India.", [1253, 2601]),
 (S, "Change into passive voice: Let us play a game.", ["Let a game be played.", "Let a game is played.", "A game let us play.", "A game was played by us."], 0,
  "For a sentence beginning with Let, the passive form is Let + object + be + past participle.", "Another example is Let the work be done.", [1493]),
 (S, "In which country were the first modern Olympic Games held in 1896?", ["France", "Greece", "United Kingdom", "Italy"], 1,
  "The first modern Olympics were held in Athens, Greece, in 1896.", "The ancient Olympic Games were also held in Greece, at Olympia.", [410]),
 (S, "What are the two parts of a common logarithm called?", ["Base and exponent", "Numerator and denominator", "Characteristic and mantissa", "Antilog and index"], 2,
  "A common logarithm has an integral part called the characteristic and a decimal part called the mantissa.", "The mantissa is always kept positive.", [2513]),
]
